from h34 import *
M=mcq;F=tf;S=short;N=num
b='<text x="360" y="26" text-anchor="middle" font-size="18" font-weight="bold">Making recycled paper</text>'
steps=[('1. Tear','old newspaper','#fde7b0'),('2. Soak','in water with methi seeds','#d4ecf7'),('3. Mash','into wet pulp','#e8d5f2'),('4. Roll','into thin sheets','#d4efd0'),('5. Dry','paper is ready!','#f6c8d0')]
for i,(a,c,col) in enumerate(steps):
    x=20+i*138
    b+=f'<rect x="{x}" y="70" width="122" height="120" rx="12" fill="{col}" stroke="#222" stroke-width="2"/><text x="{x+61}" y="115" text-anchor="middle" font-weight="bold">{a}</text><text x="{x+61}" y="145" text-anchor="middle" font-size="13">{c}</text>'
    if i<4: b+=f'<text x="{x+130}" y="135" text-anchor="middle" font-size="22">→</text>'
b+='<text x="360" y="240" text-anchor="middle" font-size="15" fill="#555">Methi (fenugreek) seeds help the pulp stick together.</text>'
svgfile('c4e-made-paper.svg',720,270,b)
chapter(4,'evs','how-things-are-made','How Things Are Made',
 ('Is my drawing book made from trees?','Pihu was painting in her drawing book when she saw a picture of trees in the newspaper. It said, recycle paper and save trees. How are trees and paper related? Pihu and her mother find out how paper is made, how we can make paper at home, and how we can look after our world by using things wisely.'),
 [('Paper comes from trees',['Pihu’s mother tells her that paper is made from trees. Her drawing book, the newspaper, paper napkins and chart papers all come from trees.','Pihu touches a pot that looks like paper, but it feels rough. Her mother explains that it is made from recycled paper.','Recycled paper is paper made again from old paper, so that we do not need to cut so many new trees.']),
  ('Making recycled paper at home',['You need old newspapers, some fenugreek seeds called methi, and water.','First tear the newspaper into small pieces and soak them in water with a few methi seeds overnight. The seeds are the binding material that helps the pieces stick together.','The next day, mash the soaked paper and seeds with a grinder or with your hands to make a wet mixture, called pulp.','Spread the paste on a flat base and roll it out into thin sheets.','Leave the sheets to dry in the sun or air, and your recycled paper is ready.','Now we can colour and decorate it, and make a greeting card or a mask.']),
  ('Colouring paper with natural ingredients',['We can colour paper with natural ingredients like turmeric, spinach, beetroot and henna.','To compare fairly, we cut the pieces of paper to the same size and use the same quantity of each ingredient.','Then we look at the colour and say if it is bright or dull. For example, turmeric gives a yellow colour.','Natural dyes come from plant parts, such as leaves, flowers, roots, seeds and stems, so they are safe to use. They are also used to colour clothes and pots.','Pihu makes a greeting card from her recycled paper and gives it to her mother as a special gift.']),
  ('How the paper in books is made',['The paper in our books looks smoother than the recycled paper we make, because it is made from wood pulp in a factory.','The steps are similar to the steps of making recycled paper, but a large number of trees have to be cut.','Making paper also needs a lot of water and energy, so we must use paper only when needed.','Long ago, people wrote on cloth, leaves and wooden boards. In India, people wrote on palm leaves called talapatra.','Paper can also be made from banana fibre, which saves trees and protects the environment.']),
  ('Different kinds of paper',['We use different papers for different jobs. Writing paper is for notebooks, newspaper is for news, and art paper is for painting.','Tissue paper is thin and soft, and it soaks up water, so it is used for cleaning.','Cardboard is thick and hard, so it is used to make boxes for packing things.','The Braille system uses tiny bumps pressed into thick paper, so that people who cannot see can read by touch.']),
  ('The 5Rs of waste',['We can follow a five-step plan to reduce waste. These are the 5Rs: Refuse, Reduce, Reuse, Repurpose and Recycle.','Refuse means saying no to things that make waste, like single-use paper cups or plastic straws.','Reduce means using less, for example writing on both sides of a page.','Reuse means using the same thing again, for example using a gift bag again.','Repurpose means using something in a new way, for example painting an old bottle to make a flower vase.','Recycle means making something new from the old, for example turning old newspapers into handmade paper.']),
  ('Being responsible',['Small changes in our daily life help the environment, save resources and reduce pollution.','A family that carries cloth bags to the shop is reusing, and a child who does not use a plastic straw is refusing.','Think of one thing you can do for each R, and try it at home and school this week.'])],
 [('Maya does not use a plastic straw for coconut water. Which R is this?',[('Maya says no to something that makes waste.','Look at the action, not the thing.'),('Saying no to waste is called Refuse.','Refuse is the first R.'),('So Maya is following Refuse.','It is the best way to avoid waste.')]),
  ('Kabir paints an old bottle and uses it as a flower vase. Which R is this?',[('Kabir uses the bottle in a new way, not the same way as before.','He did not throw it away.'),('Using something in a new way is Repurpose.','The bottle is not melted or changed in a factory.'),('So Kabir is repurposing.','Reuse is for the same purpose.')])],
 ('Explain how to make recycled paper and what the 5Rs are.',['Tear, soak with methi seeds, mash, roll and dry','Paper comes from trees, so recycling saves trees','The 5Rs are refuse, reduce, reuse, repurpose and recycle','Natural dyes come from plants and are safe'],['Paper is made from plastic','Recycling means cutting more trees','Methi seeds colour the paper']),
 ['Paper is made from trees, so we should use it carefully.','Recycled paper is made from old paper pulp, with methi seeds as binding material.','Natural colours come from plant parts like turmeric, spinach, beetroot and henna.','The 5Rs are Refuse, Reduce, Reuse, Repurpose and Recycle.','Different kinds of paper have different uses.'],
 [M('1',1,'What is paper made from?','Trees',[('Stones','Stones are not used to make paper'),('Metal','Metal is not used to make paper')],'Wood pulp from trees.'),
  M('2',1,'What are methi seeds used for when making recycled paper?','To bind the pulp together',[('To colour the paper','Natural colour comes from things like turmeric'),('To make it smell nice','They help it stick')],'Binding material.'),
  M('3',1,'Which kind of paper is thin, soft and soaks up water?','Tissue paper',[('Cardboard','Cardboard is thick and hard'),('Art paper','Art paper is for painting')],'It is used for cleaning.'),
  M('4',1,'What did people in India write on in old times?','Palm leaves (talapatra)',[('Plastic sheets','Plastic was not used then'),('Metal plates only','Palm leaves were common')],'Talapatra means palm-leaf.'),
  M('5',2,'Which R means saying no to things that make waste?','Refuse',[('Recycle','Recycle makes something new from old'),('Reuse','Reuse means using it again')],'Refuse is the first R.'),
  M('6',2,'A child writes on both sides of a page. Which R is this?','Reduce',[('Refuse','They are still using paper, but less'),('Recycle','Nothing is made from old paper')],'Reduce means using less.'),
  M('7',2,'Making toys from old newspapers is an example of ___.','Repurpose',[('Refuse','They did not say no to anything'),('Reduce','They did not use less')],'A new use for an old thing.'),
  M('8',2,'Why do we use the same size of paper and the same quantity of colour in the colour experiment?','To compare fairly',[('To waste less water','Fair comparison is the reason'),('To make the paper heavier','Size does not make it heavy')],'A fair test changes only one thing.'),
  M('9',2,'Which colour comes from turmeric?','Yellow',[('Red','Beetroot gives a reddish colour'),('Green','Spinach gives green')],'Turmeric is yellow.'),
  M('10',2,'Why is it good to recycle paper?','It saves trees, water and energy',[('It makes more waste','Recycling reduces waste'),('It uses more trees','Recycling saves trees')],'Fewer trees need to be cut.'),
  F('11',2,'Natural dyes are made from parts of plants.',True,'Leaves, flowers, roots and seeds.'),
  F('12',3,'We should use paper only when we need it.',True,'It takes trees, water and energy to make.')],
 svgs=[('c4e-made-paper','Five boxes showing the steps of making recycled paper: tear, soak, mash, roll and dry.','Recycled paper is made in five easy steps at home.')],
 keep=['recycle','pulp','5Rs'])
